#define DRIVER_VERSION			KERNEL_VERSION(0, 0x01, 0x02)

#ifndef V4L2_CID_DIGITAL_GAIN
#define V4L2_CID_DIGITAL_GAIN		V4L2_CID_GAIN
#endif

#define GC13B0_BITS_PER_SAMPLE		10
#define GC13B0_LINK_FREQ_FULL		1200000000	//2400Mbps
#define GC13B0_LINK_FREQ_376M		376000000	//752Mbps
#define GC13B0_LINK_FREQ_752M		752000000	//1504Mbps
#define GC13B0_LINK_FREQ_488M		488000000	//976Mbps

/* pixel rate = link frequency * 2 * lanes / BITS_PER_SAMPLE */
/* 4 lane */
#define GC13B0_PIXEL_RATE_FULL_4L	(GC13B0_LINK_FREQ_FULL / 10 * 4  * 2)
#define GC13B0_PIXEL_RATE_376M_4L	(GC13B0_LINK_FREQ_376M / 10 * 4  * 2)
#define GC13B0_PIXEL_RATE_752M_4L	(GC13B0_LINK_FREQ_752M / 10 * 4  * 2)
#define GC13B0_PIXEL_RATE_488M_4L	(GC13B0_LINK_FREQ_488M / 10 * 4  * 2)

/* 2 lane */
#define GC13B0_PIXEL_RATE_FULL_2L	(GC13B0_LINK_FREQ_FULL / 10 * 2  * 2)
#define GC13B0_PIXEL_RATE_376M_2L	(GC13B0_LINK_FREQ_376M / 10 * 2  * 2)
#define GC13B0_PIXEL_RATE_752M_2L	(GC13B0_LINK_FREQ_752M / 10 * 2  * 2)
#define GC13B0_PIXEL_RATE_488M_2L	(GC13B0_LINK_FREQ_488M / 10 * 2  * 2)

#define GC13B0_XVCLK_FREQ_24M		24000000

/* i2c 7bit addr: 0x4a*/
#define CHIP_ID				0x13b0
#define GC13B0_REG_CHIP_ID_H		0x03f0
#define GC13B0_REG_CHIP_ID_L		0x03f1

#define GC13B0_REG_CTRL_MODE		0x0100
#define GC13B0_MODE_SW_STANDBY		0x80
#define GC13B0_MODE_STREAMING		0x01

#define GC13B0_REG_SEXPOSURE_H		0x0200
#define GC13B0_REG_SEXPOSURE_L		0x0201
#define GC13B0_REG_EXPOSURE_H		0x0202
#define GC13B0_REG_EXPOSURE_L		0x0203
#define GC13B0_EXPOSURE_MIN		8
#define GC13B0_EXPOSURE_STEP		1
#define GC13B0_VTS_MAX			0x7fff

/* total gain */
#define GC13B0_REG_GAIN_H		0x0204
#define GC13B0_REG_GAIN_L		0x0205

/* digital gain */
#define GC13B0_REG_DGAIN_H		0x0275
#define GC13B0_REG_DGAIN_M		0x0276
#define GC13B0_REG_DGAIN_L		0x0277

#define GC13B0_AGAIN_MIN		0x400
#define GC13B0_AGAIN_MAX		0x4000 // 16 x 0x400
#define GC13B0_AGAIN_STEP		1
#define GC13B0_AGAIN_DEFAULT		0x400

#define GC13B0_REG_TEST_PATTERN		0x035d
#define GC13B0_TEST_PATTERN_BIT_MASK	BIT(0)
#define GC13B0_TEST_PATTERN_ENABLE	0x1
#define GC13B0_TEST_PATTERN_DISABLE	0x0

#define GC13B0_REG_TEST_TYPE		0x035e

#define GC13B0_REG_VTS_H		0x0340
#define GC13B0_REG_VTS_L		0x0341

#define GC13B0_REG_HTS_H		0x0342
#define GC13B0_REG_HTS_L		0x0343

#define GC13B0_FLIP_MIRROR_REG		0x0101
#define GC13B0_MIRROR_BIT_MASK		BIT(0)
#define GC13B0_FLIP_BIT_MASK		BIT(1)

#define REG_DELAY			0x0000
#define REG_NULL			0xFFFF

#define GC13B0_REG_VALUE_08BIT		1
#define GC13B0_REG_VALUE_16BIT		2
#define GC13B0_REG_VALUE_24BIT		3

#define OF_CAMERA_PINCTRL_STATE_DEFAULT	"rockchip,camera_default"
#define OF_CAMERA_PINCTRL_STATE_SLEEP	"rockchip,camera_sleep"
#define OF_CAMERA_HDR_MODE		"rockchip,camera-hdr-mode"
#define GC13B0_NAME			"gc13b0"

static const char *const gc13b0_supply_names[] = {
	"dovdd",	/* Digital I/O power */
	"dvdd",		/* Digital core power */
	"avdd",		/* Analog power */
};

#define GC13B0_NUM_SUPPLIES ARRAY_SIZE(gc13b0_supply_names)

struct regval {
	u16 addr;
	u8 val;
};

struct gc13b0_mode {
	u32 bus_fmt;
	u32 width;
	u32 height;
	struct v4l2_fract max_fps;
	u32 hts_def;
	u32 vts_def;
	u32 exp_def;
	const struct regval *global_reg_list;
	const struct regval *reg_list;
	u32 mclk;
	u32 link_freq_idx;
	u32 hdr_mode;
	u32 vc[PAD_MAX];
	u8 bpp;
	u32 lanes;
};

struct gc13b0 {
	struct i2c_client	*client;
	struct clk		*xvclk;
	struct gpio_desc	*reset_gpio;
	struct gpio_desc	*pwdn_gpio;
	struct gpio_desc	*pwren_gpio;
	struct regulator_bulk_data supplies[GC13B0_NUM_SUPPLIES];

	struct pinctrl		*pinctrl;
	struct pinctrl_state	*pins_default;
	struct pinctrl_state	*pins_sleep;

	struct v4l2_subdev	subdev;
	struct media_pad	pad;
	struct v4l2_ctrl_handler ctrl_handler;
	struct v4l2_ctrl	*exposure;
	struct v4l2_ctrl	*anal_gain;
	struct v4l2_ctrl	*digi_gain;
	struct v4l2_ctrl	*hblank;
	struct v4l2_ctrl	*vblank;
	struct v4l2_ctrl	*pixel_rate;
	struct v4l2_ctrl	*link_freq;
	struct v4l2_ctrl	*h_flip;
	struct v4l2_ctrl	*v_flip;
	struct v4l2_ctrl	*test_pattern;
	struct mutex		mutex;
	struct v4l2_fract	cur_fps;
	bool			streaming;
	bool			power_on;
	const struct gc13b0_mode *supported_modes;
	const struct gc13b0_mode *cur_mode;
	u32			cfg_num;
	u32			module_index;
	const char		*module_facing;
	const char		*module_name;
	const char		*len_name;
	u32			cur_vts;
	u32			cur_pixel_rate;
	u32			cur_link_freq;
	struct preisp_hdrae_exp_s init_hdrae_exp;
	struct cam_sw_info	*cam_sw_inf;
	bool			has_init_exp;
	bool			is_thunderboot;
	bool			is_first_streamoff;
	bool			is_standby;
	struct v4l2_fwnode_endpoint bus_cfg;
};

#define to_gc13b0(sd) container_of(sd, struct gc13b0, subdev)

